/// <summary>
///     The <c>AVAInventTransferLineDbt_Extension</c> class is the extension for <c>InventTransferLine</c>
/// </summary>
[ExtensionOf(tableStr(InventTransferLine))]
final class AVAInventTransferLineDbt_Extension
{
}

Method.Source:
/// <summary>
/// returns the last InventTransferJour record for selected line
/// </summary>
/// <returns>InventTransferJour</returns>
public InventTransferJour avaLastTransferJournal()
{
    InventTransferJour avaTransferJour;

    select firstfast avaTransferJour
        order by CreatedDateTime desc, VoucherId desc
        where avaTransferJour.TransferId == this.TransferId;

    return avaTransferJour;
}

/// <summary>
/// init values based on ProdBOM record
/// </summary>
/// <param name = "_prodBOM">ProdBOM</param>
public void avaInitProdBOM(ProdBOM _prodBOM)
{
    InventTableModule avaInventModule   = _prodBOM.inventTable().inventTableModuleInvent();
    InventDim avaInventDim              = this.inventDim();
    Qty avaQty                          = _prodBOM.RemainBOMPhysical;

    avaInventDim.inventBatchId  = InventDim::find(_prodBOM.InventDimId).inventBatchId;

    if(_prodBOM.UnitId != avaInventModule.UnitId)
    {
        avaQty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_prodBOM.ItemId, _prodBOM.InventDimId, avaQty, _prodBOM.UnitId, avaInventModule.UnitId);
    }

    this.ItemId                         = _prodBOM.ItemId;
    this.UnitId                         = avaInventModule.UnitId;
    this.QtyTransfer                    = avaQty;
    this.QtyRemainShip                  = avaQty;
    this.QtyRemainReceive               = avaQty;
    this.QtyShipNow                     = 0;
    this.QtyReceiveNow                  = 0;
    this.AutoReservation                = NoYes::No;
    this.AVAItemSet                     = NoYes::No;
    this.AVAItemSetExpanded             = NoYes::No;
    this.AVAItemSetComponent            = NoYes::No;
    this.KCS_SOCPickingReleaseIndicator = NoYes::No;
    this.InventDimId                    = InventDim::findOrCreate(avaInventDim).InventDimId;
}

/// <summary>
///    AVA <c>avaCheckAvailable</c> method.
/// </summary>
/// <param name="_showInfo">
///    <c>boolean</c> as type
/// </param>
/// <param name="_nextArrival">
///    <c>boolean</c> as type
/// </param>
/// <param name="_nextAvailability">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>TransDate</c> as type
/// </returns>
public TransDate avaCheckNextAvailability(  boolean _showInfo           = true,
                                            boolean _nextArrival        = false,    //next arrival date - nur feinterminierte PA
                                            boolean _nextAvailability   = true  )   //next availabilty date - auch grobgeplante PA
{
    // 2009: SalesLine.KCS_CheckAvailableV2()
    AVAStockAvailability    locAVAStockAvailability;

    InventTrans             locInventTrans;
    InventTransOrigin       locInventTransOrigin;
    InventTrans             locInventTransReserved;

    Transdate               nextArrivalDate;
    boolean                 nextArrivalDatefound;
    Transdate               nextAvailabilityDate;
    Transdate               locDateExpected;

    InventDim               locInventDimSalesLine;
    ReqItemTable            locReqItemTable;
    InventSum               locInventSum;
    InventDim               locInventDim;
    Qty                     locQtyAvailable;

    str                     locStrStatus;
    boolean                 locIgnoreInstance;

    #define.Production('F')
    #define.Purch('B')


    nextArrivalDate         = dateNull();
    nextAvailabilityDate    = dateNull();
    locDateExpected         = dateNull();


    locAVAStockAvailability = this.avaGetStockAvailablity();
    if(     locAVAStockAvailability != AVAStockAvailability::PartitialAvailable
        &&  locAVAStockAvailability != AVAStockAvailability::NotAvailable       )
    {
        if (_nextArrival || _nextAvailability)
        {
            return dateNull();
        }
    }

    //Bestellt reserviert
    select firstOnly locInventTrans
    where   locInventTrans.StatusIssue    == StatusIssue::ReservOrdered
        join    locInventTransOrigin
        where   locInventTransOrigin.RecId          == locInventTrans.InventTransOrigin
            &&  locInventTransOrigin.InventTransId  == this.InventTransId;

    if (locInventTransOrigin.InventTransId)
    {
        select firstOnly locInventTransReserved
        where   locInventTransReserved.StatusReceipt == StatusReceipt::Ordered
            join    locInventTransOrigin
            where   locInventTransOrigin.RecId          == locInventTransReserved.InventTransOrigin
                &&  locInventTransOrigin.InventTransId  == this.InventTransId;

        if (locInventTransReserved.RecId)
        {
            if (_showInfo)
            {
                info(strfmt("@NDX:NXAOrderedReservedP1P2P3P4P5",    locInventTransReserved.DateExpected,
                                                                    locInventTransOrigin.ReferenceCategory,
                                                                    locInventTransOrigin.ReferenceId,
                                                                    locInventTransReserved.Qty,
                                                                    this.QtyRemainShip                      )   );
            }

            if (_nextArrival)
            {
                if (locInventTransOrigin.ReferenceCategory == InventTranstype::Production)
                {
                    if (ProdTable::findTransId(locInventTransOrigin.InventTransId).SchedStatus == ProdSchedStatus::JobScheduled)
                    {
                        return locInventTransReserved.DateExpected;
                    }
                    else
                    {
                        return datenull();
                    }
                }
                else
                {
                    return locInventTransReserved.DateExpected;
                }
            }

            if (_showInfo || _nextAvailability)
            {
                return locInventTransReserved.DateExpected;
            }
        }
    }

    //Lagerauffüllung prüfen
    locInventDimSalesLine                = this.inventDim();
    locInventDimSalesLine.wMSLocationId  = '';
    locInventDimSalesLine                = InventDim::findOrCreate(locInventDimSalesLine);

    select firstOnly locReqItemTable
    where   locReqItemTable.ItemId          == this.ItemId
        &&  locReqItemTable.ReqPOType       == ReqPoType::Transfer
        &&  locReqItemTable.CovInventDimId  == locInventDimSalesLine.inventDimId;

    if (locReqItemTable)
    {
        if (_showInfo)
        {
            info(strfmt("@NDX:NXAP1P2IsFilledUpFromP3", this.itemid,
                                                        locInventDimSalesLine.InventColorId,
                                                        locReqItemTable.InventLocationIdReqMain )   );
        }
    }
    else
    {
        if (_showInfo)
        {
            info(strfmt("@NDX:NXAP1P2NoFilledUp",   this.itemid,
                                                    locInventDimSalesLine.InventColorId )   );
        }
    }

    //Verfügbare Lagermenge
    select sum(AvailPhysical), sum(PhysicalInvent)
    from locInventSum
        join locInventDim
        where   locInventSum.InventDimId        == locInventDim.inventDimId
            &&  locInventSum.ItemId             == this.ItemId
            &&  locInventSum.PhysicalInvent     > 0
            &&  locInventDim.InventColorId      == locInventDimSalesLine.InventColorId
            &&  (locInventDim.InventLocationId  == locInventDimSalesLine.InventLocationId || locInventDim.InventLocationId == locReqItemTable.InventLocationIdReqMain);

    locQtyAvailable = locInventSum.AvailPhysical;

    if (_showInfo)
    {
        info(strfmt("@NDX:NXAPhysicalP1PhysicalAvailableP2",    locInventSum.PhysicalInvent,
                                                                locInventSum.AvailPhysical  )   );
    }

    if (locQtyAvailable > this.QtyRemainShip)
    {
        nextAvailabilityDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        if (_showInfo)
        {
            info(strfmt("@NDX:NXANextAvailabilityP1",nextAvailabilityDate));
        }
        if (_nextAvailability)
        {
            return nextAvailabilityDate;
        }
    }

    //nicht reservierte Abgänge mit führeren DateExpected
    locDateExpected = InventTrans::findTransId(this.InventTransId).DateExpected;

    select sum(qty)
    from    locInventTrans
    join    locInventDim
    where   locInventTrans.DateExpected     < locDateExpected
        &&  locInventTrans.StatusIssue      == StatusIssue::OnOrder
        &&  locInventTrans.inventdimid      == locInventDim.inventDimId
        &&  locInventTrans.ItemId           == this.ItemId
        &&  locInventDim.InventColorId      == locInventDimSalesLine.InventColorId
        &&  (locInventDim.InventLocationId  == locInventDimSalesLine.InventLocationId || locInventDim.InventLocationId == locReqItemTable.InventLocationIdReqMain);

    locQtyAvailable += locInventTrans.Qty;

    if (_showInfo && locInventTrans.Qty)
    {
        info(strfmt("@NDX:NXAUnreservedOutgoingBeforeP1P2SubtotalP3",   locDateExpected,
                                                                        locInventTrans.Qty,
                                                                        locQtyAvailable     )   );
    }

    //Aufträge mit gleichen Datum und kleinerer Nummer inkl. dem eigenen Auftrages
    select sum(qty)
    from    locInventTrans
        join    locInventTransOrigin
        where   locInventTransOrigin.RecId              == locInventTrans.InventTransOrigin
            &&  locInventTransOrigin.InventTransId      == this.InventTransId
        join    locInventDim
        where   locInventTrans.DateExpected             == locDateExpected
            &&  locInventTrans.StatusIssue              == StatusIssue::OnOrder
            &&  locInventTrans.inventdimid              == locInventDim.inventDimId
            &&  locInventTrans.ItemId                   == this.ItemId
            &&  locInventDim.InventColorId              == locInventDimSalesLine.InventColorId
            &&  (locInventDim.InventLocationId          == locInventDimSalesLine.InventLocationId || locInventDim.InventLocationId == locReqItemTable.InventLocationIdReqMain)
            &&  locInventTransOrigin.ReferenceCategory  == InventTranstype::InventTransfer
            &&  locInventTransOrigin.ReferenceId        <= this.TransferId;

    locQtyAvailable += locInventTrans.Qty;

    if (_showInfo && locInventTrans.Qty)
    {
        info(strfmt("@NDX:NXAUnreservedOutgoingAtP1ToOrderP2SubtotalP3",    locDateExpected,
                                                                            locInventTrans.Qty,
                                                                            locQtyAvailable     )   );
    }

    //Ermittlung der Zugänge
    while select locInventTrans
        join    locInventTransOrigin
        where   locInventTransOrigin.RecId          == locInventTrans.InventTransOrigin
        //    &&  locInventTransOrigin.InventTransId  == this.InventTransId   // open, not related to actual SalesLine
        join    locInventDim
        order by locInventTrans.DateExpected asc
        where   locInventTrans.inventdimid          == locInventDim.inventDimId
            &&  locInventTrans.ItemId               == this.ItemId
            &&  locInventTrans.StatusReceipt        == StatusReceipt::Ordered  // mehr Statis?
            &&  locInventDim.InventColorId          == locInventDimSalesLine.InventColorId
            &&  (locInventDim.InventLocationId      == locInventDimSalesLine.InventLocationId || locInventDim.InventLocationId == locReqItemTable.InventLocationIdReqMain)
    {
        locIgnoreInstance   = false;
        locStrStatus        = '';

        switch(locInventTransOrigin.ReferenceCategory)
        {
            case Inventtranstype::Sales:
                break;

            case Inventtranstype::Purch:
                if (Purchline::findInventTransId(locInventTransOrigin.InventTransId).ConfirmedDlv != global::dateNull())
                {
                    locStrStatus = locStrStatus + #Purch;
                }
                if (!nextArrivalDate)
                {
                    nextArrivalDatefound = true;
                }
                break;

            case Inventtranstype::Production:
                if (ProdTable::findTransId(locInventTransOrigin.InventTransId).SchedStatus == ProdSchedStatus::JobScheduled)
                {
                    locStrStatus = locStrStatus + #Production;
                    if (!nextArrivalDate)
                    {
                        nextArrivalDatefound = true;
                    }
                }
                break;

            case Inventtranstype::ProdLine:
                break;

            case Inventtranstype::TransferOrderReceive:
                if (!nextArrivalDate)
                {
                    nextArrivalDatefound = true;
                }
                break;

            case Inventtranstype::TransferOrderShip:
                break;

            default:
                locIgnoreInstance = true;
                break;
        }
        if (!locIgnoreInstance)
        {
            locQtyAvailable += locInventTrans.Qty;

            if(_showInfo)
            {
                info(strfmt("@NDX:NXAP1P2P3P4P5SubtotalP6", locInventTrans.DateExpected,
                                                            locInventTransOrigin.ReferenceCategory,
                                                            locInventTransOrigin.ReferenceId,
                                                            locStrStatus,
                                                            locInventTrans.Qty,
                                                            locQtyAvailable                         )   );
            }

            if (locQtyAvailable >= 0 && !nextAvailabilityDate)
            {
                nextAvailabilityDate = locInventTrans.DateExpected;

                if (_showInfo)
                {
                    info(strfmt("@NDX:NXANextAvailabilityP1", nextAvailabilityDate));
                }
                if (_nextAvailability)
                {
                    return nextAvailabilityDate;
                }
            }

            if (!nextArrivalDate && nextArrivalDatefound)
            {
                nextArrivalDate = locInventTrans.DateExpected;

                if (_showInfo)
                {
                    info(strfmt("@NDX:NXANextGoodsReceiptP1", nextArrivalDate));
                }
                if (_nextArrival)
                {
                    return nextArrivalDate;
                }
            }
        }
    }

    //wenn nächste Verfügbarkeit keinen Wert hat, dann errechnetes Versanddatum
    if (_nextAvailability)
    {
        if (_showInfo)
        {
            info(strfmt("@NDX:NXANextAvailabilityCalculatedShippingDateP1", this.ShipDate));
        }
        return this.ShipDate;
    }
    else
    {
        return datenull();
    }
}

/// <summary>
