/// <summary>
///     AVA <c>avaPhysicalReservedAbilityForShippingInSalesUnit</c> method.
///     AVA - Schneider 26.08.2024
/// </summary>
/// <returns>
///     <c>SalesQtyReservPhysical</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display SalesQtyReservPhysical avaPhysicalReservedAbilityForShippingInSalesUnit()
{
    SalesQtyReservPhysical  salesQtyReservPhysical;

    salesQtyReservPhysical = this.avaPhysicalReservedAbilityForShipping();

    if (!salesQtyReservPhysical)
    {
        return 0;
    }

    return this.avaUnitConvertInvent2Sales(salesQtyReservPhysical);
}

/// <summary>
///     AVA <c>avaUnitConvertInvent2Sales</c> method.
///     AVA - Schneider 26.08.2024
/// </summary>
/// <param name="_inventQty">
///     <c>InventQty</c> as type
/// </param>
/// <returns>
///     <c>SalesQty</c> as type
/// </returns>
public SalesQty avaUnitConvertInvent2Sales(InventQty _inventQty)
{
    return EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(this.ItemId,
                                                                                 this.InventDimId,
                                                                                 _inventQty,
                                                                                 this.inventTable_IN().inventUnitId(),
                                                                                 this.UnitId,
                                                                                 NoYes::Yes);
}

/// <summary>
///     AVA <c>avaPhysicalAvailForShipping</c> method.
///     AVA - Schneider 23.08.2024
/// </summary>
/// <returns>
///     <c>AVAPhysicalAvailForShipping</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display AVAPhysicalAvailForShipping avaPhysicalAvailForShipping()
{
    AVAPhysicalAvailForShipping locAVAPhysicalAvailForShipping;
    InventQtyAvailPhysical      locInventQtyAvailPhysical;

    locAVAPhysicalAvailForShipping  = this.avaPhysicalAvailAbilityForShipping() - this.avaPhysicalReservedAbilityForShipping();
    locInventQtyAvailPhysical       = this.avaAvailPhysical();
    if(     locInventQtyAvailPhysical
        &&  locInventQtyAvailPhysical < locAVAPhysicalAvailForShipping)
    {
        locAVAPhysicalAvailForShipping = locInventQtyAvailPhysical;
    }

    return locAVAPhysicalAvailForShipping;
}

/// <summary>
///     AVA <c>avaGetStockAvailablityStandard</c> method.
/// </summary>
/// <param name="_inventTransferLine">
///     <c>InventTransferLine</c> as type
/// </param>
/// <returns>
///     <c>AVAStockAvailability</c> as type
/// </returns>
public AVAStockAvailability avaGetStockAvailablityStandard(InventTransferLine _inventTransferLine = this)
{
    AVAStockAvailability    retVal;

    InventQty               tmpQty;
    InventQty               locInventQtyAvailable;
    InventQty               locInventQtyRemaining;
    InventQty               locInventQtyPicked;
    InventQty               locInventQtyReserved;
    InventQty               locInventQtyReservedpdsCW;

    locInventQtyRemaining   = _inventTransferLine.QtyRemainShip;
    locInventQtyPicked      = _inventTransferLine.qtyReservedOnOrder();
    [   locInventQtyReserved,
        locInventQtyReservedpdsCW   ]   = _inventTransferLine.qtyReservedPhysical();

    if(this.avaHasShippingAbility())
    {
        if(locInventQtyRemaining - locInventQtyReserved <= 0.0)
        {
            return AVAStockAvailability::Available;
        }
       locInventQtyAvailable   = _inventTransferLine.avaPhysicalAvailForShipping();
        // locInventQtyReserved    = _inventTransferLine.avaPhysicalReservedAbilityForShipping();
        // allready contained in locInventQtyAvailable
        locInventQtyReserved    = 0.0;
        // locInventQtyAvailable already without reserved qty, so tmpQty calculation will be corrected
    }
    else
    {
        locInventQtyAvailable   = _inventTransferLine.avaAvailPhysical();
    }

    tmpQty                  = locInventQtyRemaining - locInventQtyPicked - locInventQtyReserved;

    if(locInventQtyAvailable >= tmpQty)
    {
        retVal = AVAStockAvailability::Available;
    }
    else if(    locInventQtyAvailable > 0
            &&  locInventQtyAvailable < tmpQty  )
    {
        retVal = AVAStockAvailability::PartitialAvailable;
    }
    else if(locInventQtyAvailable <= 0)
    {
        retVal = AVAStockAvailability::NotAvailable;
    }

    return retVal;
}

