/// <summary>
///    AVA <c>avaReservedPhysical</c> method.
///    Method to get current reserved quantity for specific inventDim
/// </summary>
/// <returns>
///     <c>InventQtyReservPhysical</c> as type
/// </returns>
public display InventQtyReservPhysical avaReservedPhysical()
{
    InventQtyReservPhysical         retVal;

    InventDim                       locInventDim;
    InventDimParm                   locInventDimParmCriteria;
    InventTransIdSumSingleStatus    locInventTransIdSumSingleStatus;

    if (!this.InventTransId) // ToDo: || !this.isStocked())
    {
        return 0;
    }

    //return -InventTransIdSumSingleStatus::qtyReservPhysical(InventTransOriginSalesLine::findInventTransOriginId(this.DataAreaId, this.InventTransId));

    locInventDim.clear();
    locInventDim = InventDim::findOrCreate(this.inventDim());
    locInventDimParmCriteria.initFromInventDim(locInventDim);

    locInventTransIdSumSingleStatus = InventTransIdSumSingleStatus::newTransOriginIdStatus( InventTransOriginTransferShip::findInventTransOriginId( this.DataAreaId,
                                                                                                                                                    this.TransferId,
                                                                                                                                                    this.LineNum    ),
                                                                                            StatusReceipt::None,
                                                                                            StatusIssue::ReservPhysical                                                 );
    locInventTransIdSumSingleStatus.parmInventDimCriteria(locInventDim);
    locInventTransIdSumSingleStatus.parmInventDimParmCriteria(locInventDimParmCriteria);

    retVal = locInventTransIdSumSingleStatus.reservPhysical() * (-1);

    return retVal;
}

/// <summary>
///    AVA <c>avaRemainQtyNotReserved</c> method.
/// </summary>
/// <param name="_shippingAbility">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>InventQty</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display InventQty avaRemainInventQtyNotReserved(boolean _shippingAbility = false)
{
    InventQty retVal;

    boolean                 locHasShippingAbility;
    AVAShippingAbility      locShippingAbility;

    locShippingAbility          = this.avaShippingAbility();
    locHasShippingAbility       = locShippingAbility == AVAShippingAbility::Control;
    if(     _shippingAbility 
        &&  locHasShippingAbility   )
    {
        retVal  = this.qtyRemainShip - this.avaPhysicalReservedAbilityForShipping();
    }
    else
    {
        retVal  = this.qtyRemainShip - this.avaReservedPhysical();
    }

    if(retVal < 0.0)
    {
        retVal = 0.0;
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaGetReservableQty</c> method.
/// </summary>
/// <param name="_inventTransferLine">
///    <c>InventTransferLine</c> as type
/// </param>
/// <param name="_shippingAbility">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>InventTransferQty</c> as return value
/// </returns>
public InventTransferQty avaGetReservableQty(   InventTransferLine  _inventTransferLine = this,
                                                boolean             _shippingAbility    = false)
{
    InventTransferQty       retVal;

    InventTransferLine      itemSetInventTransferLineParent;
    InventTransferLine      itemSetInventTransferLineSearch;
    AVAStockAvailability    locAVAStockAvailability;
    AVAStockAvailability    locAVAStockAvailabilitySub;

    InventTransferQty       qtyPerItemSet;
    InventTransferQty       qtyItemSetsNeeded;
    InventTransferQty       qtyItemSetsAvailable;
    InventTransferQty       qtyItemSetsCoveredCurrent;
    InventTransferQty       qtyItemSetsCoveredTotal;

    InventTransId           weakestInventTransId;

    void calculateNeededItemSetQty()
    {
        qtyPerItemSet               = itemSetInventTransferLineSearch.QtyTransfer / minOne(itemSetInventTransferLineParent.QtyTransfer);
        qtyItemSetsNeeded           = itemSetInventTransferLineSearch.QtyRemainShip / minOne(qtyPerItemSet);
        if(_shippingAbility)
        {
            qtyItemSetsAvailable    = itemSetInventTransferLineSearch.avaPhysicalAvailForShipping() / minOne(qtyPerItemSet);
        }
        else
        {
            qtyItemSetsAvailable    = itemSetInventTransferLineSearch.avaAvailPhysical() / minOne(qtyPerItemSet);
        }
        qtyItemSetsCoveredCurrent   = qtyItemSetsAvailable / minOne(qtyItemSetsNeeded);
        //qtyItemSetsCoveredCurrent   = itemSetInventTransferLineSearch.avaAvailPhysical() / minOne(itemSetInventTransferLineSearch.RemainSalesPhysical);
        if(qtyItemSetsCoveredCurrent > qtyItemSetsNeeded)
        {
            qtyItemSetsCoveredCurrent = qtyItemSetsNeeded;
        }
        else
        {
            qtyItemSetsCoveredCurrent = qtyItemSetsAvailable;
        }
    }

    locAVAStockAvailability = this.avaGetStockAvailablity();

    if(locAVAStockAvailability == AVAStockAvailability::NotAvailable)
    {
        retVal = 0;
    }
    else if(locAVAStockAvailability == AVAStockAvailability::Available)
    {
        retVal = this.QtyRemainShip;
    }
    else if(locAVAStockAvailability == AVAStockAvailability::PartitialAvailable)
    {
        retVal = this.QtyRemainShip;

        if(     this.AVAItemSetComponent
            ||  (this.AVAItemSet && this.avaIsItemSetExpanded())    )
        {
            if(this.AVAItemSet)
            {
                itemSetInventTransferLineParent = this;
            }
            if(this.AVAItemSetComponent && this.AVAItemSetParent)
            {
                itemSetInventTransferLineParent = InventTransferLine::findTransIdShip(this.AVAItemSetParent);
            }

            qtyItemSetsCoveredTotal = itemSetInventTransferLineParent.QtyRemainShip;

            while select itemSetInventTransferLineSearch
            where   itemSetInventTransferLineSearch.TransferId          == itemSetInventTransferLineParent.TransferId
                &&  itemSetInventTransferLineSearch.AVAItemSetParent    == itemSetInventTransferLineParent.InventTransId
            {
                locAVAStockAvailabilitySub = itemSetInventTransferLineSearch.avaGetStockAvailablity();
                if(locAVAStockAvailabilitySub == AVAStockAvailability::Available)
                {
                    calculateNeededItemSetQty();
                }
                else if(locAVAStockAvailabilitySub == AVAStockAvailability::PartitialAvailable)
                {
                    calculateNeededItemSetQty();
                }

                if(qtyItemSetsCoveredCurrent < qtyItemSetsCoveredTotal)
                {
                    qtyItemSetsCoveredTotal = qtyItemSetsCoveredCurrent;
                    weakestInventTransId    = itemSetInventTransferLineSearch.InventTransId;
                }

            }

            itemSetInventTransferLineSearch = InventTransferLine::findTransIdShip(weakestInventTransId);
            calculateNeededItemSetQty();

            retVal = qtyItemSetsCoveredCurrent;
        }
        else  // itemSet not expanded or standard sales line
        {
            retVal = this.avaAvailPhysical();
        }
    }
    return retVal;
}

/// <summary>
///    AVA <c>avaRemainInventQtyReservable</c> method.
/// </summary>
/// <param name="_shippingAbility">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>InventQty</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display InventQty avaRemainInventQtyReservable(boolean _shippingAbility = false)
{
    InventQty retVal;
    InventQty locInventQty;

    retVal = 0.0;

    if(this.QtyRemainShip > 0.0)                        // inventQty remaining
    {
        retVal = this.avaRemainInventQtyNotReserved(_shippingAbility);

        if(retVal > 0.0)                                // inventQty remaining not reserved
        {
            locInventQty = this.avaGetReservableQty(this,
                                                    _shippingAbility);
            if(locInventQty > 0.0)                      // inventQty to reserve exist
            {
                if(retVal > locInventQty)
                {
                    retVal = locInventQty;
                }
            }
        }
    }
    return retVal;
}

/// <summary>
///    AVA <c>avaUpdateInventTransferTableKCS_PickingReleaseIndicator</c> method.
/// </summary>
public void avaUpdateInventTransferTableKCS_PickingReleaseIndicator()
{
    InventTransferTable         locInventTransferTable;
    KCS_PickingReleaseIndicator locKCS_PickingReleaseIndicator;
    KCS_PickingReleaseIndicator locKCS_PickingReleaseIndicatorCalc;

    locInventTransferTable = this.InventTransferTable();

    locKCS_PickingReleaseIndicator      = locInventTransferTable.KCS_PickingReleaseIndicator;

    locKCS_PickingReleaseIndicatorCalc  = locInventTransferTable.avaCalcKCS_PickingReleaseIndicator();

    if(locKCS_PickingReleaseIndicator != locKCS_PickingReleaseIndicatorCalc)
    {
        ttsbegin;
        locInventTransferTable.selectForUpdate(true);
        locInventTransferTable.KCS_PickingReleaseIndicator = locKCS_PickingReleaseIndicatorCalc;
        locInventTransferTable.update();
        ttsCommit;
    }
}

/// <summary>
///    AVA <c>avaCheckTransferInventSiteAndLocation</c> method.
/// </summary>
/// <param name="_from">
///    <c>InventDim</c> as type
/// </param>
/// <param name="_to">
///    <c>InventDim</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as type
/// </returns>
public boolean avaCheckForTransferInventSiteAndLocation(InventDim _from = this.inventDim(), InventDim _to = this.inventDim())
{
    boolean                 retVal;
    boolean                 locCheckFailed;
    boolean                 locPysicalReservatedFound;
    boolean                 locOpenScanActivityFound;

    InventTransferLine      itemSetInventTransferLineParent;
    InventTransferLine      itemSetInventTransferLineSearch;

    void checkSingleInventTransferLine(InventTransferLine _inventTransferLine)
    {
        if(!locPysicalReservatedFound && _inventTransferLine.avaReservedPhysical() > 0)
        {
            locCheckFailed              = checkFailed("@NDX:NXATransferOfSalesLineReservatedNotPossible");
            retVal                      = false;
            locPysicalReservatedFound   = true;
        }
        if(!locOpenScanActivityFound && _inventTransferLine.avaOpenWHSWorkTableExists().RecId)
        {
            locCheckFailed              = checkFailed("@NDX:NXATransferOfSalesLineWithOpenScanActivityNotPossible");
            retVal                      = false;
            locOpenScanActivityFound    = true;
        }
    }

    retVal = true;

    if(     this.AVAItemSetComponent
        ||  (this.AVAItemSet && this.avaIsItemSetExpanded())    )
    {
        if(this.AVAItemSet)
        {
            itemSetInventTransferLineParent = this;
        }
        if(this.AVAItemSetComponent && this.AVAItemSetParent)
        {
            itemSetInventTransferLineParent = InventTransferLine::findTransIdShip(this.AVAItemSetParent);
        }
        while select itemSetInventTransferLineSearch
            where   itemSetInventTransferLineSearch.TransferId          == itemSetInventTransferLineParent.TransferId
                &&  itemSetInventTransferLineSearch.AVAItemSetParent    == itemSetInventTransferLineParent.InventTransId
        {
            checkSingleInventTransferLine(itemSetInventTransferLineSearch);
        }
    }
    else
    {
        checkSingleInventTransferLine(this);
    }

    return retVal;
}

/// <summary>
/// Retrieves the amount of the inventory items that are marked for the sales order line.
/// </summary>
/// <returns>
/// The amount of the inventory that is marked for the inventory transaction that is related to the
/// sales order line.
/// </returns>
public InventQtyMarked qtyMarked()
{
    InventTransOriginId     inventTransOriginId;
    InventQtyMarked         inventQtyMarked;

    if (0 == 0) //ToDo: Check in InventTransferLine this.isStocked())
    {
        inventTransOriginId = InventTransOriginSalesLine::findInventTransOriginId(this.DataAreaId, this.InventTransId);
        if (inventTransOriginId)
        {
            inventQtyMarked = InventTransOrigin::qtyMarked(inventTransOriginId);
        }
    }

    return inventQtyMarked;
}

/// <summary>
///    AVA <c>avaReserveInventTransferLine</c> method.
/// </summary>
/// <param name="_inventTransferLine">
///    <c>InventTransferLine</c> as type
/// </param>
/// <param name="_qtyToReserve">
///    <c>InventQty</c> as type
/// </param>
/// <param name="_unreserve">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaReserveInventTransferLine(InventTransferLine  _inventTransferLine = this,
                                            InventQty           _qtyToReserve       = 0,
                                            boolean             _unreserve          = false )
{
    boolean                         retVal;

    InventTransIdSumSingleStatus    locInventTransIdSumSingleStatus;
    InventTransferLine              locInventTransferLine;
    InventMovement                  locInventMovement;
    InventDim                       locInventDim;
    InventDimParm                   locInventDimParmCriteria;
    InventQtyReservPhysical         locOldReservedQty;
    InventQtyReservPhysical         locNewReservedQty;
    InventUpd_Reservation           locInventUpd_Reservation;
    InventQty                       locInventQtyToReserve;

    /* moved to InventTransferLine.avaReservedPhysical()
    // Inline method to get current reserved quantity for specific inventDim
    InventQtyReservPhysical getReservedQty()
    {
        locInventDimParmCriteria.initFromInventDim(locInventDim);

        locInventTransIdSumSingleStatus = InventTransIdSumSingleStatus::newTransOriginIdStatus( InventTransOriginTransferShip::findInventTransOriginId(locInventTransferLine.DataAreaId, locInventTransferLine.TransferId, locInventTransferLine.LineNum),
                                                                                                StatusReceipt::None,
                                                                                                StatusIssue::ReservPhysical);
        locInventTransIdSumSingleStatus.parmInventDimCriteria(locInventDim);
        locInventTransIdSumSingleStatus.parmInventDimParmCriteria(locInventDimParmCriteria);

        return locInventTransIdSumSingleStatus.reservPhysical();
    }
    */

    retVal                  = true;

    // InventTransferLine
    locInventTransferLine   = _inventTransferLine;
    locInventMovement       = InventTrans::findTransId(locInventTransferLine.InventTransId).inventMovement(true);

    // Build inventDim-Record, where the quantity should be reserved
    locInventDim.clear();
    locInventDim = InventDim::findOrCreate(locInventTransferLine.inventDim());

    // Get current physical reserved Quantity
    //locOldReservedQty           = getReservedQty();
    locOldReservedQty           = locInventTransferLine.avaReservedPhysical();


    // Set quanity which should be reserved (negative values to reserve, postive value to unreserve)
    if(_qtyToReserve)
    {
        locInventQtyToReserve   = -_qtyToReserve;
    }
    else
    {
        locInventQtyToReserve   = _inventTransferLine.QtyRemainShip; //ToDo: _salesLine.reserveQty();
    }

    if(_unreserve)
    {
        locInventQtyToReserve = locInventQtyToReserve * (-1);
    }

    locInventUpd_Reservation    = InventUpd_Reservation::newInventDim(  locInventMovement,
                                                                        locInventDim,
                                                                        locInventQtyToReserve,
                                                                        true                    );
    locInventUpd_Reservation.updateNow();

    // Get new reserved quantity
    //locNewReservedQty = getReservedQty();
    locNewReservedQty = locInventTransferLine.avaReservedPhysical();

    // Compare old and new reserved quantity to identify if reservation failed
    if(     locOldReservedQty   == locNewReservedQty
        &&  _qtyToReserve       > 0)
    {
        error("@NDX:NXAReservationFailed");
        retVal = false;
    }

    return retVal;
}

/// <summary>
/// Initializes the transfer quantity and the record in the <c>InventDim</c> table.
/// </summary>
/// <param name="_inventTable">
/// The record in the inventory table.
/// </param>
/// <param name="_inventDimId">
/// The inventory dimension id to be used for initializing.
/// </param>
public void initFromInventTable(InventTable _inventTable, InventDimId _inventDimId )
{
    next initFromInventTable(_inventTable, _inventDimId);

    // itemSets
    this.AVAItemSet = _inventTable.AVAItemSet;
}

/// <summary>
///    AVA <c>avaItemSetItemId</c> method.
/// </summary>
/// <returns>
///     <c>AVAItemSetItemId</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display AVAItemSetItemId avaItemSetItemId()
{
    AVAItemSetItemId retVal;

    if(this.AVAItemSetComponent)
    {
        retVal = InventTransferLine::findTransIdShip(this.AVAItemSetParent).ItemId;
    }
    else if(this.AVAItemSet)
    {
        retVal = this.ItemId;
    }
    return retVal;
}

/// <summary>
///    AVA <c>avaIsItemSetExpanded</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as type
/// </returns>
public boolean avaIsItemSetExpanded()
{
    boolean             retVal;

    InventTransferLine  locInventTransferLine;

    if (!this.AVAItemSet)
    {
        return false;
    }

    if (!this.AVAItemSetExpanded)
    {
        return false;
    }

    if (this.RecId)
    {
        select firstonly RecId
        from    locInventTransferLine
        where   locInventTransferLine.TransferId        == this.TransferId
            &&  locInventTransferLine.AVAItemSetParent  == this.InventTransId;
        retVal = locInventTransferLine.RecId != 0;
    }
    else
    {
        retVal = false;
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaIsAVAItemSetPositionExpandable</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaIsItemSetPositionExpandable()
{
    boolean retVal;

    retVal = (this.AVAItemSet && !this.AVAItemSetExpanded);

    return retVal;
}

/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    AVAItemSetInventTransferLineExplodeBOM  locAVAItemSetLineExplodeBOM;
    Args                                    locArgs;

    next modifiedField(_fieldId);

    if(     this.AVAItemSet
        &&  this.avaIsItemSetExpanded()  )
    {
        locArgs = new Args();
        locArgs.record(this);
        if(this.isFormDataSource())
        {
            locArgs.caller(this.dataSource().formRun());
        }

        locAVAItemSetLineExplodeBOM = AVAItemSetInventTransferLineExplodeBOM::newFromArgs(locArgs);
        locAVAItemSetLineExplodeBOM.init(false); // init without BOMBaseVersion
        locAVAItemSetLineExplodeBOM.parmInventTransferLineOrig(this.orig());
        locAVAItemSetLineExplodeBOM.parmInventTransferLineNew(this);
        locAVAItemSetLineExplodeBOM.parmInventTransferLineChanged(false);
        locAVAItemSetLineExplodeBOM.parmInventTransferLineChangedFieldId(_fieldId);
        locAVAItemSetLineExplodeBOM.updateItemSetComponents();
    }

    switch (_fieldId)
    {
        case fieldNum(InventTransferLine, AVAProdSchedDate):
            if(     this.AVAProdSchedDate != dateNull() 
                &&  this.AVAProdSchedDate > this.ShipDate   )
            {
                this.ShipDate       = this.AVAProdSchedDate;

                if(this.AVAProdSchedDate > this.ReceiveDate)
                {
                    this.ReceiveDate    = this.AVAProdSchedDate;
                }
            }
            break;
    }
}

/// <summary>
///    AVA <c>avaItemSetInventTransferLineSetKCS_SOCPickingReleaseIndicator</c> method.
/// </summary>
public void avaItemSetInventTransferLineSetKCS_SOCPickingReleaseIndicator(boolean _includingSiblingComponents = false)
{
    InventTransferLine  locInventTransferLine;

    ttsbegin;

    if(this.AVAItemSetComponent)
    {
        if(_includingSiblingComponents)
        {
            while select locInventTransferLine
            where   locInventTransferLine.InventTransId     != this.InventTransId
                &&  locInventTransferLine.AVAItemSetParent  == this.AVAItemSetParent
            {
                if(locInventTransferLine.RecId && locInventTransferLine.KCS_SOCPickingReleaseIndicator != this.KCS_SOCPickingReleaseIndicator)
                {
                    locInventTransferLine.selectForUpdate(true);
                    locInventTransferLine.KCS_SOCPickingReleaseIndicator = this.KCS_SOCPickingReleaseIndicator;
                    locInventTransferLine.update();
                }
            }
        }

        select firstonly locInventTransferLine
        where   locInventTransferLine.AVAItemSet
            &&  locInventTransferLine.InventTransId == this.AVAItemSetParent;

        if(locInventTransferLine.RecId && locInventTransferLine.KCS_SOCPickingReleaseIndicator != this.KCS_SOCPickingReleaseIndicator)
        {
            locInventTransferLine.selectForUpdate(true);
            locInventTransferLine.KCS_SOCPickingReleaseIndicator = this.KCS_SOCPickingReleaseIndicator;
            locInventTransferLine.update();
        }
    }

    ttsCommit;
}

/// <summary>
///    AVA <c>avaItemSetGetPossibleReservationQty</c> method.
/// </summary>
/// <returns>
///    <c>InventTransferQty</c> as return value
/// </returns>
public InventTransferQty avaItemSetGetPossibleReservationQty()
{
    InventTransferQty   retVal;

    InventTransferLine  locInventTransferLineItemSet;

    if(this.AVAItemSetComponent)
    {
        locInventTransferLineItemSet = InventTransferLine::findTransIdShip(this.AVAItemSetParent);
    }
    else if(this.avaIsItemSetExpanded())
    {
        locInventTransferLineItemSet = this;
    }
    else
    {
        retVal = this.avaGetReservableQty();
    }

    return retVal;
}

/// <summary>
/// Extension of update method
/// </summary>
/// <param name = "_parameters">anytype</param>
/// <param name = "_updateHeader">NoYes</param>
public void update(
    anytype _parameters,
    NoYes _updateHeader)
{
    if (this.AVAItemSet == NoYes::Yes && this.AVAItemSetExpanded == NoYes::Yes)
    {
        this.QtyRemainShip = 0;
        this.QtyRemainReceive = 0;
    }

    if(this.QtyTransfer != this.orig().QtyTransfer)
    {
        ProdTable avaProdTable = this.avaInventTransHasProduction();

        if(avaProdTable.RecId)
        {
            this.QtyTransfer = this.orig().QtyTransfer;
            throw error(strFmt("@NDX:NXAQtyChangeProdTableError", avaProdTable.ProdId, avaProdTable.ProdStatus));
        }
    }

    next update(_parameters,_updateHeader);
}

/// <summary>
///    Deletes the record.
/// </summary>
public void delete()
{
    ProdTable avaProdTable = this.avaInventTransHasProduction();

    if(avaProdTable.RecId)
    {
        throw error(strFmt("@NDX:NXAInventLineDeleteProdTableError", this.ItemId, avaProdTable.ProdId, avaProdTable.ProdStatus));
    }

    next delete();

}

 /// <summary>
 /// Checks if any associated InventTrans record is connected to a ProdTable record
 /// </summary>
 /// <returns>ProdTable</returns>
public ProdTable avaInventTransHasProduction()
 {
     InventTrans         avaInventTrans;
     InventTransOrigin   avaInventTransOrigin, avaInventTransOrigin_Prod;
     ProdTable           avaProdTable;

     select firstonly avaInventTrans
         join avaInventTransOrigin
         join avaInventTransOrigin_Prod
         join avaProdTable
         where avaInventTrans.InventTransOrigin          == avaInventTransOrigin.RecId
         && avaInventTrans.MarkingRefInventTransOrigin   == avaInventTransOrigin_Prod.RecId
         && avaProdTable.InventTransId                   == avaInventTransOrigin_Prod.InventTransId
         && avaInventTransOrigin.ReferenceCategory       == InventTransType::TransferOrderShip
         && (avaInventTransOrigin.InventTransId      == this.InventTransId
             || avaInventTransOrigin.InventTransId   == this.InventTransIdTransitTo
             || avaInventTransOrigin.InventTransId   == this.InventTransIdTransitFrom
             || avaInventTransOrigin.InventTransId   == this.InventTransIdReceive
             || avaInventTransOrigin.InventTransId   == this.InventTransIdScrap);

     return avaProdTable;
 }
